import AppKit

/// Eingebettetes PayPal-Logo (PP-Monogramm, PNG base64) — selbst-enthalten, ohne
/// Resource-Bundle (wie ReweLogoAsset). Genutzt für Menüleiste + Flyout + Pillen
/// des PayPal-Slots. Quelle: PayPal-Marke (nominative Nutzung zur Konto-Kennzeichnung).
enum PayPalLogoAsset {
    static let image: NSImage? = {
        guard let data = Data(base64Encoded: base64.replacingOccurrences(of: "\n", with: "")) else { return nil }
        return NSImage(data: data)
    }()

    private static let base64 = """

"""
}
